	private static Kernel kernel(int groupWidth) {
		if (groupWidth == 1) {
			return new Kernel(1, List.of(new EnumerateDomain(0, 0)), new Aggregate(new int[] { 0 }, outputs(0), null,
					OutputMods.none()));
		}
		return new Kernel(2, List.of(new EnumerateDomain(0, 0), new EnumerateDomain(1, 1)),
				new Aggregate(new int[] { 0, 1 }, outputs(1), null, OutputMods.none()));
	}

	private static AggregateOutput[] outputs(int valueColumn) {
		return new AggregateOutput[] { AggregateOutput.countStar(), AggregateOutput.minId(valueColumn),
				AggregateOutput.maxId(valueColumn) };
	}

	private static KernelContext context(int groupWidth, LmdbQueryMemoryManager.QueryLedger ledger) {
		long[][] domains = groupWidth == 1 ? new long[][] { values(64, 1) }
				: new long[][] { values(20, 1), values(20, 100) };
		return new KernelContext(new NativeAdjacency[0], new long[0], new long[0], domains, new AggregateHooks())
				.withMemoryLedger(ledger);
	}

	private static long[] values(int count, int first) {
		long[] values = new long[count];
		for (int i = 0; i < count; i++) {
			values[i] = first + i;
		}
		return values;
	}

	private static List<long[]> drainFirstRowAndRemainder(JaninoKernel execution, int stride,
			List<List<Long>> expected) {
		long[] firstBuffer = new long[stride];
		assertEquals(1, execution.fill(firstBuffer, 1), "the aggregate must produce its first group");
		List<long[]> rows = new ArrayList<>();
		rows.add(Arrays.copyOf(firstBuffer, stride));
		long[] buffer = new long[stride * Math.min(32, Math.max(1, expected.size()))];
		while (true) {
			int filled = execution.fill(buffer, buffer.length / stride);
			if (filled == 0) {
				return rows;
			}
			for (int row = 0; row < filled; row++) {
				rows.add(Arrays.copyOfRange(buffer, row * stride, (row + 1) * stride));
			}
		}
	}

	private static List<List<Long>> expectedRows(int groupWidth) {
		List<List<Long>> rows = new ArrayList<>();
		if (groupWidth == 1) {
			for (long group : values(64, 1)) {
				rows.add(List.of(group, 1L, group, group));
			}
			return rows;
		}
		for (long left : values(20, 1)) {
			for (long right : values(20, 100)) {
				rows.add(List.of(left, right, 1L, right, right));
			}
		}
		return rows;
	}

	private static Set<List<Long>> asRowSet(List<long[]> rows) {
		Set<List<Long>> result = new HashSet<>();
		for (long[] row : rows) {
			List<Long> values = new ArrayList<>(row.length);
			for (long value : row) {
				values.add(value);
			}
			result.add(values);
		}
		return result;
	}

	private static final class FirstAllocationOnly implements KernelRuntime.MemoryAccount {
		private boolean allocated;
		private long usedBytes;

		@Override
		public boolean tryReserve(long bytes) {
			if (bytes == 0L) {
				return true;
			}
			if (allocated) {
				return false;
			}
			allocated = true;
			usedBytes += bytes;
			return true;
		}

		@Override
		public void release(long bytes) {
			usedBytes -= bytes;
		}
	}

	private static final class AggregateHooks implements KernelHooks {
		@Override
		public boolean testFilter(int filterId, long a0, long a1, long a2) {
			return true;
		}

		@Override
		public long computeBind(int bindId, long a0, long a1) {
			return a0;
		}

		@Override
		public int compareValues(long left, long right) {
			return Long.compare(left, right);
		}

		@Override
		public boolean isNumeric(long id) {
			return false;
		}

		@Override
		public double doubleValue(long id) {
			return 0.0;
		}

		@Override
		public void accumulateNumeric(int aggregateId, int groupId, long valueId) {
			throw new AssertionError("the HASHED memory fixture uses id extrema, not numeric hooks");
		}
	}
